CREATE TABLE [dbo].[contactMeanInAzure](	  [inboundId] INT NOT NULL	, [tenantId] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [clientId] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [clientSecret] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [instance] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [apiUrl] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, CONSTRAINT [PK_contactMeanInAzure] PRIMARY KEY ([inboundId] ASC))